  width: 800px;
  padding-bottom: 12px;
}
.fill-chart-modal .chart-ports {
  display: flex;
}
.fill-chart-modal .chart-ports label {
  line-height: 40px;
}
.fill-chart-modal .oris-select {
  display: inline-block;
  width: 300px;
  padding: 0 12px;
}
.fill-chart-modal .oris-select button.btn {
  width: 100%;
}
.fill-chart-modal .modal-table {
  border: 1px solid #DCDCDC;
  margin: 12px 0 24px 0;
  line-height: 1;
}

.fill-chart-modal tbody tr td:not(:last-child) {
  border-right: 1px solid #DCDCDC;
}

.fill-chart-modal .port-describe {
  color: #666;
  line-height: 18px;
  margin-top: 8px;
}

.fill-chart-modal .chart-title {
  text-align: left;
  font-weight: bold;
}

.fill-chart-modal .loaded-content {
  display: none;
}

.fill-chart-modal .no-charts {
  text-align: center;
