</div>
<script>
{
  $(function() {
    $(''body'').on(''click'', ''.action-protect-describe'', function() {
      let isBuyer = $(this).attr(''data-account'') === ''buyer''; // 展示Buyer 或者 Seller
      let needBtn = $(this).attr(''data-usebtn'') === ''1''; // 底部点击按钮
      let $desc = $(''#protectDescribeModal'');
      if (isBuyer) {
        $desc.find(''.action-seller'').hide();
        $desc.find(''.action-buyer'').show();
        needBtn && $desc.find(''.modal-footer'').show();
        $desc.find(''.describe-modal'').css(''cssText'', ''width: 800px !important''); // 产品详情页有样式污染
      }
      $(''#protectDescribeModal'').modal();
    })
  })
}
</script>


