        window.performance.navigation.type == 2)) {
        globalYzc.$router.reload()
      }
    }, false)
    var productInfoPage = {
      rebate_other_confirm: ''You are in the rebate agreement of this product. If you purchase at margin price, futures price or tiered price, the quantity will not be counted into the rebate agreement. Do you confirm to continue?'',
      initPage: function() {
        $("#originalFlag").on("click",function () {
          $("#myModalSwapperImgModal").modal(''show'');
        });
        $(''body'').on(''click'', ''.action-bid'', function(){
          if (!false ||  null) {
            productInfoPage.openBidModal(this)
          }
          else {
            const href = globalYzc.$router.to({ path: ''customer/profile/main&scroll_view=business'' })
            const msg = `VAT information is required to complete the purchase. Click <a class="color-#2861ce underline" href=":url" target="_blank">here</a> to provide VAT info.`.replace(/:url/, href)
            layer.alert(msg, {
              title: ''Attention'',
              skin: ''oris-layer oris-platform-layer'',
              btn: [''OK''],
              closeBtn: 0,
            }, function (index) {
              layer.closeAll();
            });
          }
        });

        $("#margin_bid_modal").on("hidden.bs.modal", function () {
          $(this).removeData("bs.modal");
          $("#margin_bid_modal_content").html("");
          $(''.oris-buyer'').css(''overflow-y'',''auto'');
        });
        $("#rebates_bid_modal").on("hidden.bs.modal", function () {
            $(this).removeData("bs.modal");
            $("#rebates_bid_modal_content").html("");
        });
        // 每次隐藏时，清除数据。确保点击时，重新加载
        $("#futuresQuickViewNew").on("hidden.bs.modal", function () {
            $(this).removeData("bs.modal");
            $("#futuresQuickViewNewContent").html("");
        });
         $("#know_rule_modal").on("hidden.bs.modal", function () {
          $(this).removeData("bs.modal");
          $("#know_rule_modal_content").html("");
          $(''.oris-buyer'').css(''overflow-y'',''auto'');
        });

        $("#question_know_modal").on("hidden.bs.modal", function () {
          $(this).removeData("bs.modal");
          $("#question_know_modal_content").html("");
          $(''.oris-buyer'').css(''overflow-y'',''auto'');
        });
      },
      openBidModal: function(that) {
        var bidType = $(that).attr(''data-type''); // bid点击类型
        var id = $(that).attr(''data-id'');
        var isQuick = $(that).attr(''data-isquick'');
        productInfoPage.handleTransactionModal(bidType, id, isQuick); // 复杂交易弹框
      },
      handleTransactionModal: function(type, id, isQuick) {
        switch (type) {
          case ''margin'':
            productInfoPage.loadMarginModal();
            break;
          case ''future'':
            productInfoPage.loadFuturesModal(id, isQuick)
            break;
        }
      },
      loadMarginModal: function () {
        if (window.isRebatesPending) {
            layer.confirm(productInfoPage.rebate_other_confirm, {
                title: ''Confirm'',
                skin: ''oris-layer'',
                btnAlign:"c",
                btn: [''Yes'', ''No''] //按钮
            }, function () {
                layer.closeAll();
                productInfoPage.showMarginModal();
            });
        } else {
            productInfoPage.showMarginModal();
        }
      },
      showMarginModal: function() {
        let myModalSelector = $("#margin_bid_modal");
        myModalSelector.modal({
            remote: "https://www.gigab2b.com/index.php?route=product/product/showMarginBidModal&product_id=747431"+ `&sold_qty=${window.quantity}&flag=0`,
            backdrop: ''static'',
            keyboard: false
        });
        $(''.modal-open'').css(''overflow-y'',''hidden'');
      },
      loadFuturesModal: function(contractId, isQuick) {
        if (window.isRebatesPending) {
          layer.confirm(productInfoPage.rebate_other_confirm, {
              title: ''Confirm'',
              skin: ''oris-layer'',
              btnAlign:"c",
            btn: [''Yes'', ''No''] //按钮
          }, function () {
            layer.closeAll();
            productInfoPage.showFuturesModal(contractId, isQuick);
          });
        } else {
          productInfoPage.showFuturesModal(contractId, isQuick);
        }
      },
      showFuturesModal: function(contractId, isQuick) {
        var myModalSelector = $("#futuresQuickViewNew");
        let url = `index.php?route=product/product/showFuturesBidModal&product_id=747431`;
        if(contractId) {
          url += `&contract_id=${contractId}`
        }
        if (isQuick) {
          url += ''&quick=1'';
        }
        // 请求后台获取详细信息
        myModalSelector.modal({
            remote: url,
            backdrop: ''static'',
            keyboard: false
        });
      }
    }
    $(function(){
      productInfoPage.initPage();
    })
    // 兼容老弹框内调用
    function showLayerTip(tipType, content, option, fun) {
        switch (tipType) {
            case ''msg'':
                layer.msg(
                    content,
                    option,
                    fun
                );
                break;
            case ''alert'':
                layer.alert(
                    content,
                    option,
                    fun
                );
                break;
            default:
                return
        }
    }
    /**
     *进行运算
     *三个参数分别是要运算的两个数和运算符
     */
    function operation(a, b, op, precision) {
        let o1 = toInteger(a);
        let o2 = toInteger(b);
        let n1 = o1.num;
        let n2 = o2.num;
        let t1 = o1.times;
        let t2 = o2.times;
        let max = t1 > t2 ? t1 : t2;
        let result = null;
        switch (op) {
            case ''add'':
                if (t1 === t2) {
                    result = n1 + n2;
                } else if (t1 > t2) {
                    result = n1 + n2 * (t1 / t2);
                } else {
                    result = n1 * (t2 / t1) + n2;
                }
                result = result / max;
                break;
            case ''subtract'':
                if (t1 === t2) {
                    result = n1 - n2;
                } else if (t1 > t2) {
                    result = n1 - n2 * (t1 / t2);
                } else {
                    result = n1 * (t2 / t1) - n2;
                }
                result = result / max;
                break;
            case ''multiply'':
                result = (n1 * n2) / (t1 * t2);
                break;
            case ''divide'':
                result = (n1 / n2) / (t2 / t1);
                break;
        }
        if (isInteger(precision) && precision >= 0) {
            result = result + "";
            let len = result.length;
            let dotIndex = result.indexOf(".");
            if (dotIndex === -1) {
                result = Number(result).toFixed(precision);
            } else {
                let dotIndexBefore = dotIndex + precision;
                let dotIndexAfter = dotIndexBefore + 1;
                if (dotIndexAfter < len) {
                    let n = result.substr(dotIndexAfter, 1);
                    if (precision === 0) {
                        //为0时dotIndexBefore用的是小数点，所以要减一
                        dotIndexBefore--;
                    }
                    let m = result.substr(dotIndexBefore, 1);
                    result = result.slice(0, dotIndexBefore);
                    if (n > 4) {
                        if (m === ''9'') {
                            //防止进位
                            if (precision === 0) {
                                m = m + ''.9'';
                            } else {
                                m = m + ''9'';
                            }
                        } else {
                            m = Number(m) + 1;
                        }
                    }
                    result = Number(result + m).toFixed(precision);
                }
                result = Number(result).toFixed(precision);
            }
        }
        return result;
    }
    /*判断obj是否为一个整数*/
    function isInteger(obj) {
        return Math.floor(obj) === obj;
    }
    /**
     * 将一个浮点数转换成整数，返回整数和倍数
     * 如 3.14 》》314  倍数是100
     */
    function toInteger(floatNum) {
        let ret = {times: 1, num: 0};

        //是整数
        if (isInteger(floatNum)) {
            ret.num = floatNum;
            return ret;
        }

        let strfi = floatNum + '''';
        //查找小数点的下标
        let dotPos = strfi.indexOf(''.'');
        //获取小数的位数
        let len = strfi.substr(dotPos + 1).length;
        //Math.pow(10,len)指定10的len次幂。
        let time = Math.pow(10, len);

        //将浮点数转化为整数
        let intNum = parseInt(floatNum * time + 0.5, 10);
        ret.times = time;
        ret.num = intNum;
        return ret;
    }
  }

</script>




