    // 兼容老弹框内调用
    function showLayerTip(tipType, content, option, fun) {
        switch (tipType) {
            case ''msg'':
                layer.msg(
                    content,
                    option,
                    fun
                );
                break;
            case ''alert'':
                layer.alert(
                    content,
                    option,
                    fun
                );
                break;
            default:
                return
        }
    }
    /**
     *进行运算
     *三个参数分别是要运算的两个数和运算符
     */
    function operation(a, b, op, precision) {
        let o1 = toInteger(a);
        let o2 = toInteger(b);
        let n1 = o1.num;
        let n2 = o2.num;
        let t1 = o1.times;
        let t2 = o2.times;
        let max = t1 > t2 ? t1 : t2;
        let result = null;
        switch (op) {
            case ''add'':
                if (t1 === t2) {
                    result = n1 + n2;
                } else if (t1 > t2) {
                    result = n1 + n2 * (t1 / t2);
                } else {
                    result = n1 * (t2 / t1) + n2;
                }
                result = result / max;
                break;
            case ''subtract'':
                if (t1 === t2) {
                    result = n1 - n2;
                } else if (t1 > t2) {
                    result = n1 - n2 * (t1 / t2);
                } else {
                    result = n1 * (t2 / t1) - n2;
                }
                result = result / max;
                break;
            case ''multiply'':
                result = (n1 * n2) / (t1 * t2);
                break;
            case ''divide'':
                result = (n1 / n2) / (t2 / t1);
                break;
        }
        if (isInteger(precision) && precision >= 0) {
            result = result + "";
            let len = result.length;
            let dotIndex = result.indexOf(".");
            if (dotIndex === -1) {
                result = Number(result).toFixed(precision);
            } else {
                let dotIndexBefore = dotIndex + precision;
                let dotIndexAfter = dotIndexBefore + 1;
                if (dotIndexAfter < len) {
                    let n = result.substr(dotIndexAfter, 1);
                    if (precision === 0) {
                        //为0时dotIndexBefore用的是小数点，所以要减一
                        dotIndexBefore--;
                    }
                    let m = result.substr(dotIndexBefore, 1);
                    result = result.slice(0, dotIndexBefore);
                    if (n > 4) {
                        if (m === ''9'') {
                            //防止进位
                            if (precision === 0) {
                                m = m + ''.9'';
                            } else {
                                m = m + ''9'';
                            }
                        } else {
                            m = Number(m) + 1;
                        }
                    }
                    result = Number(result + m).toFixed(precision);
                }
                result = Number(result).toFixed(precision);
            }
        }
        return result;
    }
    /*判断obj是否为一个整数*/
    function isInteger(obj) {
        return Math.floor(obj) === obj;
    }
    /**
     * 将一个浮点数转换成整数，返回整数和倍数
     * 如 3.14 》》314  倍数是100
     */
    function toInteger(floatNum) {
        let ret = {times: 1, num: 0};

        //是整数
        if (isInteger(floatNum)) {
            ret.num = floatNum;
            return ret;
        }

        let strfi = floatNum + '''';
        //查找小数点的下标
        let dotPos = strfi.indexOf(''.'');
        //获取小数的位数
        let len = strfi.substr(dotPos + 1).length;
        //Math.pow(10,len)指定10的len次幂。
        let time = Math.pow(10, len);

        //将浮点数转化为整数
        let intNum = parseInt(floatNum * time + 0.5, 10);
        ret.times = time;
        ret.num = intNum;
        return ret;
    }
  }

</script>




