<div class="modal fade fill-chart-modal" tabindex="-1" role="dialog" data-backdrop="static" id="fillChartModal">
  <div class="modal-dialog oris-modal">
    <div class="modal-content">
      <div class="modal-header">
        <button type="button" class="close" data-dismiss="modal" aria-hidden="true" a11y-processed="true" aria-label="click">
          <i class="giga icon-V10_danchuangguanbi close-icon"></i>
        </button>
        <div class="modal-title">Estimated Ocean Freight Charge</div>
      </div>
      <div class="modal-body">
        <div class="chart-ports">
          <label>Port</label>
          <span class="oris-select">
            <div class="dropdown bootstrap-select bs3"><select id="portSelect" placeholder="请选择" class=""></select><button type="button" tabindex="-1" class="btn dropdown-toggle btn-default bs-placeholder" data-toggle="dropdown" role="combobox" aria-owns="bs-select-1" aria-haspopup="listbox" aria-expanded="false" data-id="portSelect" title="Nothing selected" a11y-processed="true" aria-label="click"><div class="filter-option"><div class="filter-option-inner"><div class="filter-option-inner-inner">Nothing selected</div></div> </div><span class="bs-caret"><span class="caret"></span></span></button><div class="dropdown-menu open"><div class="inner open" role="listbox" id="bs-select-1" tabindex="-1"><ul class="dropdown-menu inner " role="presentation"></ul></div></div></div>
          </span>
        </div>
        <div class="port-describe">The estimate is based on the total ocean freight charge data for the most recent 6 months. Total ocean freight charge is averaged to a single product by volume based on a 40HQ container.</div>
        <div class="loaded-content">
          <table class="modal-table oris-table">
            <thead>
              <tr>
                <th>Total Ocean<br>Freight Charge/ Container</th>
                <th>Ocean Freight Charge/ Unit</th>
                <th>Unit Price<br>(excluding ocean freight charge)</th>
                <th>Estimated Unit Price</th>
              </tr>
            </thead>
            <tbody>
              <tr></tr>
            </tbody>
          </table>
          <div class="chart-title">Total Ocean Freight Charge / Unit Trend</div>
          <div id="myFillChart" style="height: 230px;"></div>
        </div>
        <div class="no-charts">
          <img src="https://www.gigab2b.com/public/image/icons/empty.png?v=1748518548" a11y-processed="true" alt="empty">
          <div>No records</div>
        </div>
      </div>
    </div>
  </div>
</div>
<script>
{
  $(function() {
    fillChartCom.initBind();
  })
  var fillChartCom = {
    activeProductId: null,  // 产品id
    activeUnitPrice: 0,     // 单价（不含海运费）
    activeContractId: null, // 合约ID (非必填)
    activePorts: null,      // 港口（非必填，英文逗号隔开）
    estimatedUnitPrice: null, // 综合海运费预估单价
    initBind: function() {
      // 点击触发弹框
      $(''body'').on(''click'', ''.action-fillchart'', function() {
        fillChartCom.activeProductId = $(this).attr(''data-productid'');
        fillChartCom.activeUnitPrice = $(this).attr(''data-price-unsea'');
        fillChartCom.estimatedUnitPrice = $(this).html();
        fillChartCom.activeContractId = $(this).attr(''data-contract-id'');
        fillChartCom.activePorts = $(this).attr(''data-port'');
        $(''#fillChartModal'').modal();
        $(''#fillChartModal'').find(''.loaded-content'').hide();
        $(''#fillChartModal'').find(''.no-charts'').show();
        fillChartCom.getPortService();
      })
      $(''#portSelect'').selectpicker().on(''change'', function() {
        fillChartCom.portSelectChange($(this).val());
      })
    },
    // 获取港口接口
    getPortService: function() {
      var loadingIndex = layer.load(1, {
        shade: [1, ''#000''],
      });
      let url = ''index.php?route=common/freight/getPorts'';
      fillChartCom.activeContractId && (url+=`&contract_id=${fillChartCom.activeContractId}`);
      fillChartCom.activePorts && (url+=`&port=${fillChartCom.activePorts}`)
      $.ajax({
        url: url,
        type: ''get'',
        dataType: ''json'',
        success: function(json) {
          if (json.code == 200 && json.data && json.data.ports && json.data.ports.length > 0) {
            let options = '''';
            json.data.ports.forEach(function(one) {
              options += `<option value="${one}">${one}</option>`
            })
            $(''#portSelect'').html(options).selectpicker(''refresh''); // 港口下拉框内容
            fillChartCom.portSelectChange($(''#portSelect'').val(), loadingIndex)
          } else {
            layer.close(loadingIndex);
          }
        },
        error: function(xhr, ajaxOptions, thrownError) {
          layer.close(loadingIndex);
          alert(thrownError + "\r\n" + xhr.statusText + "\r\n" + xhr.responseText);
        }
      });
    },
    // 根据港口获取
    portSelectChange: function(port, loadingIndex) {
      if (!port) {
        return;
      }
      loadingIndex = loadingIndex || layer.load(1, {shade: [1, ''#000''],});
      $.ajax({
        url: `index.php?route=common/freight/getPortSeaFreight&product_id=${fillChartCom.activeProductId}&port=${port}`,
        type: ''get'',
        dataType: ''json'',
        success: function(json) {
          layer.close(loadingIndex);
          if (json.code == 200) {
            $(''#fillChartModal'').find(''.loaded-content'').show();
            $(''#fillChartModal'').find(''.no-charts'').hide();
            fillChartCom.renderTable(json.data);
            if (json["data"]["records"] && json["data"]["records"].length > 0) {
              fillChartCom.renderCharts(json.data.currency, json.data.records);
            }
          } else {
            $(''#fillChartModal'').find(''.loaded-content'').hide();
            $(''#fillChartModal'').find(''.no-charts'').show();
          }
        },
        error: function(xhr, ajaxOptions, thrownError) {
          layer.close(loadingIndex);
          alert(thrownError + "\r\n" + xhr.statusText + "\r\n" + xhr.responseText);
        }
      })
    },
    renderTable: function(data) {
      let currency = data.currency;
      let decimal = currency == ''JPY'' ? 0 : 2;
      let minPrice = mathematical.MathToPrice(mathematical.accAdd(+data.product_min_sea_freight, +fillChartCom.activeUnitPrice, 4), decimal);
      let maxPrice = mathematical.MathToPrice(mathematical.accAdd(+data.product_max_sea_freight, +fillChartCom.activeUnitPrice, 4), decimal);
      let tableTr = `<td>${fillChartCom.handleSamePriceSection(+data.min_sea_freight, +data.max_sea_freight, currency)}</td>
                     <td>${fillChartCom.handleSamePriceSection(+data.product_min_sea_freight, +data.product_max_sea_freight, currency)}</td>
                     <td>${mathematical.formatPrice(currency, +fillChartCom.activeUnitPrice)}</td>
                     <td>${fillChartCom.handleSamePriceSection(+minPrice, +maxPrice, currency)}</td>`
      $(''#fillChartModal'').find(''table tbody tr'').html(tableTr)
    },
    // 处理价格区间显示
    handleSamePriceSection: function(min, max, currency) {
      if (min === max) {
        return mathematical.formatPrice(currency, min);
      } else {
        return mathematical.formatPrice(currency, min) + '' - '' + mathematical.formatPrice(currency, max);
      }
    },
    renderCharts: function(currency, records) {
      var myChart = echarts.init(document.getElementById(''myFillChart''));
      var xAxisData = records.map(function(one) { return one.date })
      var yAxisData = records.map(function(one) { return one.estimated_sea_freight })
      myChart.setOption({
        tooltip: {
          trigger: ''axis'',
          backgroundColor: ''#fff'',
          borderColor: ''#dcdcdc'',
          borderWidth: 1,
          padding: 12,
          textStyle: {
            color: ''#333''
          },
          formatter: function(data) {
            let price = mathematical.formatPrice(currency, +data[0][''value''])
            return `${data[0][''name'']}<br>${data[0][''seriesName'']}: ${price}`
          }
        },
        legend: {
          data: ["Ocean Freight Charge / Unit"],
          left: ''center'',
          bottom: ''0px''
        },
        grid: {
          top: ''20px'',
          left: ''40px'',
          right: ''40px'',
          bottom: ''44px''
        },
        xAxis: {
          type: ''category'',
          boundaryGap: false,
          data: xAxisData
        },
        yAxis: {
          type: ''value'',
          boundaryGap: [0, ''100%'']
        },
        series: [{
          name: "Ocean Freight Charge / Unit",
          type: ''line'',
          smooth: true, // 开启平滑处理。true的平滑程度相当于0.5
          symbol: ''circle'',
          showSymbol: true,
          symbolSize: 10,
          itemStyle: {
            normal: {
              color: ''rgb(97, 146, 249)'', //  图形的颜色。
            }
          },
          position: ''left'',
          data: yAxisData
        }]
      })
    }
  }
}
</script><style>
