INSERT OR IGNORE INTO clean_products (id, run_id, source, url, external_id, title, price, currency, description, images, specifications, scraped_at, ingested_at) VALUES (5, 'ap-1778432923090-aqpxpl', 'amazon-product', 'https://www.amazon.com/dp/B07WG51N84?th=1', 'B07WG51N84', 'Pipishell Nightstands Set of 2, Bamboo Stackable Bedside Table, Night Stands with Storage Shelf, Small Bed Side Tables, 2-Tier End Table for Bedroom, Dorm and Small Space Storage (Natural)', 43.99, 'USD', 'Stack Your Style: This bedside table set includes two stackable side tables that can be arranged together or separately to maximize your living space. Stack them together to create a 25.3″ tall table with 3 levels of storage with easy access to the open shelving.
Premium Bamboo Wood: Crafted from high-quality bamboo, these Pipishell nightstands are exceptionally sturdy to hold up to 22 lbs each. Bamboo wood is a sustainable material that provides both strength and durability for long-lasting use.
Perfect for Small Spaces: The bamboo side tables are designed to fit in compact living spaces. The versatile 15.7″ W x 11.4″ Dx 16.5″ H size allows you to make the most of your available space without sacrificing style or functionality.
Modular Design: Pipishell end tables can be used as coffee tables, nightstands, sofa side tables, and more. Placed in front of each other, the stackable tables can create a larger tabletop to arrange magazines and decorations in your living room or den.
Complement Your Décor: The bedside tables feature a classic bamboo finish that can add style and character to any room. Whether you prefer a modern, vintage, or traditional look, the bamboo nightstands can blend in perfectly with any décor.

.aplus-v2 .aplus-content-wrapper {
        position: relative;
        overflow: hidden;
    }

    .aplus-v2 .container-with-background-image {
        width: 100%;
        height: 100%;
        background-repeat: no-repeat;
        background-size: cover;
    }

  
    function logShoppableMetrics(moduleName, showsAddToCart) {
        if (window.ue && window.ue.count) {
            window.ue.count("aplus:shoppable:" + moduleName + ":addToCart", showsAddToCart ? 1 : 0);
        }
    }


                                                 From the brand   
    
            
    /*
     * Used when device = desktop
     * Configured in: configuration/brazil-config/global/brand-story.cfg
     */

    /* Because the carousel is implemented as an ol list,
       any lists in the card text will have a secondary list style (letters).
       This will give an incorrect appearance to viewers,
       so we set all lists to the primary list style (numbers). */
    .aplus-brand-story-card ol li {
        list-style: decimal;
    }

    /* Top level containers */
    .aplus-module .apm-brand-story-hero {
      -moz-box-sizing: border-box;
      -webkit-box-sizing: border-box;
      box-sizing: border-box;
      width: 1464px;
      height: 625px;
      background-color: #fff;
    }

    .aplus-module .apm-brand-story-card {
      -moz-box-sizing: border-box;
      -webkit-box-sizing: border-box;
      box-sizing: border-box;
      width: 362px;
      height: 453px;
      background-color: #fff;
    }

    .apm-brand-story-hero,
    .apm-brand-story-card {
      -moz-box-sizing: border-box;
      -webkit-box-sizing: border-box;
      box-sizing: border-box;
      position: relative;
      width: 100%;
      height: 100%;
      float: none;
    }

    .aplus-module.brand-story-card-1-four-asin .apm-brand-story-card {
      /* Only 12px to account for image cell border */
      padding: 12px;
    }

    /* Full background image (Hero 1 & Card 2) */
    .aplus-module .apm-brand-story-background-image {
      -moz-box-sizing: border-box;
      -webkit-box-sizing: border-box;
      box-sizing: border-box;
      overflow: hidden;
      position: absolute;
      width: 100%;
      height: 100%;
    }

    .aplus-module .apm-brand-story-background-image img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    /* Card 1 small images */
    .aplus-module .apm-brand-story-image-grid {
      -moz-box-sizing: border-box;
      -webkit-box-sizing: border-box;
      box-sizing: border-box;
      padding: 0px;
      margin: auto;
      display: flex;
      flex-flow: row wrap;
    }

    .aplus-module .apm-brand-story-image-grid .apm-brand-story-image-grid-item {
